function debounce(fn, wait = 300) {
  let timer;
  return (...args) => {
    clearTimeout(timer);
    timer = setTimeout(() => fn(...args), wait);
  };
}

function throttle(fn, interval = 300) {
  let last = 0;
  return (...args) => {
    const now = Date.now();
    if (now - last >= interval) {
      last = now;
      fn(...args);
    }
  };
}

searchInput.addEventListener('input', debounce(e => search(e.target.value)));
window.addEventListener('scroll', throttle(updateProgressBar, 100));

const animal = {
  eat() { return `${this.name} eats`; },
};

const dog = Object.create(animal); // dog's prototype is animal
dog.name = 'Rex';
dog.bark = () => 'Woof';

console.log(dog.eat());   // found on animal via the chain
console.log(Object.hasOwn(dog, 'eat'));    // false — inherited
console.log(Object.hasOwn(dog, 'name'));   // true — own
